              repeating-linear-gradient(to left, rgb(255, 145, 0, 0.5), rgb(255, 0, 0, 0.5), rgb(255, 0, 140, 0.5), rgb(255, 0, 0, 0.5), rgb(255, 145, 0, 0.5) 50px),
              rgba(193, 193, 193, 0.673);
}
